// A game's own icon from generated bytes: PE resource trees of both widths, `.ico` and `.icns`
// files, DIBs and PNGs, and every truncation and a run of corrupted bytes, which must come out as
// nothing rather than a crash. Pictures are decoded back to check what was kept.
#include "game_icon.hpp"

#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <optional>
#include <span>
#include <string>
#include <vector>

#include "gpu2d/image/decode.hpp"
#include "gpu2d/image/png_encoder.hpp"
#include "library/pe_resources.hpp"
#include "support/pe_bytes.hpp"
#include "support/scratch_dir.hpp"
#include "support/test_main.hpp"

namespace {

namespace fs = std::filesystem;
namespace image = gpu2d::image;
namespace pe = opensu::library::pe;
using opensu::artwork::gameIcon;
using opensu::artwork::iconOfIcns;
using opensu::artwork::iconOfIco;
using opensu::artwork::iconOfProgram;
using opensu::library::Game;
using opensu::test::icoFile;
using opensu::test::iconDib;
using opensu::test::iconGroup;
using opensu::test::iconPaletteDib;
using opensu::test::PeBytes;
using opensu::test::peProgram;
using opensu::test::PeResource;

void expect(bool condition, const char* what) {
    if (!condition) {
        std::fprintf(stderr, "FAIL: %s\n", what);
        std::exit(1);
    }
}

void write(const fs::path& file, const PeBytes& bytes) {
    fs::create_directories(file.parent_path());
    std::ofstream out{file, std::ios::binary};
    out.write(reinterpret_cast<const char*>(bytes.data()),
              static_cast<std::streamsize>(bytes.size()));
}

image::Bitmap decoded(const std::optional<std::string>& png, const char* what) {
    std::string error;
    std::optional<image::Bitmap> bitmap;
    if (png) {
        bitmap = image::decode(std::as_bytes(std::span{png->data(), png->size()}), error);
    }
    if (!bitmap) {
        expect(false, what);
        return {};
    }
    return *std::move(bitmap);
}

/// A real PNG of `side` pixels, as `.ico` and `.icns` files hold them.
PeBytes pngOf(std::uint32_t side) {
    const std::vector<std::uint8_t> rgba(std::size_t{side} * side * 4, 200);
    std::string error;
    const std::string png = image::encodePng(rgba, side, side, error);
    expect(!png.empty(), "a PNG to embed");
    return {png.begin(), png.end()};
}

/// A program with a 16 and a 48 pixel red icon in group 7, and a blue one in group 9.
std::vector<PeResource> iconResources() {
    return {{pe::iconType, 1, iconDib(16, 0, 255, 0)},
            {pe::iconType, 2, iconDib(48, 255, 0, 0)},
            {pe::iconType, 3, iconDib(32, 0, 0, 255)},
            {pe::iconGroupType, 7, iconGroup({1, 2}, {16, 48})},
            {pe::iconGroupType, 9, iconGroup({3}, {32})}};
}

void testProgram(const fs::path& root) {
    for (const bool wide : {false, true}) {
        const fs::path file = root / (wide ? "wide.exe" : "narrow.exe");
        write(file, peProgram(iconResources(), wide));
        const image::Bitmap largest = decoded(iconOfProgram(file, 0), "a group's icon");
        expect(largest.width == 48 && largest.height == 48, "the largest of the first group");
        const std::size_t shown = largest.offset(40, 40);
        expect(largest.rgba[shown] == 255 && largest.rgba[shown + 1] == 0 &&
                   largest.rgba[shown + 3] == 255,
               "BGRA comes out as RGBA");
        const std::size_t clear = largest.offset(2, 2);
        expect(largest.rgba[clear + 3] == 0, "rows run bottom first, and alpha is kept");
        expect(decoded(iconOfProgram(file, 1), "the second group").width == 32,
               "a shortcut's index counts groups");
        expect(decoded(iconOfProgram(file, -9), "a group by id").width == 32,
               "a negative index is a resource id");
        expect(decoded(iconOfProgram(file, 5), "no such group").width == 48,
               "an index past the end takes the first group");
    }
    const fs::path bare = root / "bare.exe";
    write(bare, peProgram({{pe::versionType, 1, {1, 2, 3}}}));
    expect(!iconOfProgram(bare, 0), "a program with no icon has none");
}

void testDibs() {
    const image::Bitmap masked =
        decoded(iconOfIco(icoFile({iconDib(32, 10, 20, 30, false)}, {32})), "a masked DIB");
    expect(masked.rgba[masked.offset(1, 1) + 3] == 0 &&
               masked.rgba[masked.offset(30, 30) + 3] == 255,
           "with no alpha of its own, the AND mask says what shows");
    const image::Bitmap palette =
        decoded(iconOfIco(icoFile({iconPaletteDib(16, 9, 8, 7)}, {16})), "a palette DIB");
    const std::size_t at = palette.offset(3, 3);
    expect(palette.rgba[at] == 9 && palette.rgba[at + 1] == 8 && palette.rgba[at + 2] == 7 &&
               palette.rgba[at + 3] == 255,
           "an 8-bit icon is read through its palette");
}

void testIco() {
    const PeBytes png = pngOf(256);
    const image::Bitmap picked = decoded(
        iconOfIco(icoFile({iconDib(32, 1, 2, 3), png, iconDib(16, 1, 2, 3)}, {32, 256, 16})),
        "an .ico with a PNG");
    expect(picked.width == 256, "the largest image, a PNG kept as it is");
    PeBytes broken = png;
    broken.resize(40);
    expect(decoded(iconOfIco(icoFile({broken, iconDib(32, 1, 2, 3)}, {256, 32})), "a broken one")
                   .width == 32,
           "an image that does not decode gives way to the next");
}

void testIcns() {
    const auto element = [](const char* type, const PeBytes& payload) {
        PeBytes out{static_cast<std::uint8_t>(type[0]), static_cast<std::uint8_t>(type[1]),
                    static_cast<std::uint8_t>(type[2]), static_cast<std::uint8_t>(type[3])};
        const std::size_t size = payload.size() + 8;
        for (const unsigned shift : {24U, 16U, 8U, 0U}) {
            out.push_back(static_cast<std::uint8_t>(size >> shift));
        }
        out.insert(out.end(), payload.begin(), payload.end());
        return out;
    };
    PeBytes file = element("icns", {});
    for (const PeBytes& each : {element("ic07", pngOf(128)), element("ic09", pngOf(512)),
                                element("is32", PeBytes(64, 7)), element("ic08", pngOf(256))}) {
        file.insert(file.end(), each.begin(), each.end());
    }
    expect(decoded(iconOfIcns(file), "an .icns").width == 512, "the largest PNG element");
    expect(!iconOfIcns(element("icns", {})), "no PNG element, no icon");
}

void testOversized() {
    PeBytes huge = iconDib(16, 1, 2, 3);
    opensu::test::putLe(huge, 4, 0x7FFFFFFF, 4);
    expect(!iconOfIco(icoFile({huge}, {16})), "a claimed size past any icon's is refused");
    opensu::test::putLe(huge, 4, 2000, 4);
    expect(!iconOfIco(icoFile({huge}, {16})), "and so is one the bytes do not hold");
}

/// A deterministic generator, so a failure repeats.
std::uint32_t next(std::uint32_t& state) {
    state = (state * 1664525U) + 1013904223U;
    return state >> 8U;
}

void testHostile(const fs::path& root) {
    const PeBytes program = peProgram(iconResources());
    const fs::path file = root / "hostile.exe";
    for (std::size_t size = 0; size < program.size(); size += 7) {
        write(file, PeBytes{program.begin(), program.begin() + static_cast<std::ptrdiff_t>(size)});
        static_cast<void>(iconOfProgram(file, 0));
    }
    const PeBytes ico = icoFile({iconDib(32, 1, 2, 3), pngOf(64)}, {32, 64});
    for (std::size_t size = 0; size < ico.size(); ++size) {
        static_cast<void>(iconOfIco(std::span{ico}.first(size)));
        static_cast<void>(iconOfIcns(std::span{ico}.first(size)));
    }
    std::uint32_t state = 1;
    for (int round = 0; round < 3000; ++round) {
        PeBytes mangledProgram = program;
        PeBytes mangledIco = ico;
        for (int flips = 0; flips < 8; ++flips) {
            // The headers and directories, where an offset turns into a wild read.
            mangledProgram[next(state) % 1400] = static_cast<std::uint8_t>(next(state));
            mangledIco[next(state) % 120] = static_cast<std::uint8_t>(next(state));
        }
        write(file, mangledProgram);
        static_cast<void>(iconOfProgram(file, static_cast<std::int32_t>(next(state) % 5) - 2));
        static_cast<void>(iconOfIco(mangledIco));
    }
}

void testGameIcon(const fs::path& root) {
    const fs::path folder = root / "game";
    write(folder / "game.exe", peProgram(iconResources()));
    write(folder / "other.ico", icoFile({iconDib(24, 1, 2, 3)}, {24}));
    Game game;
    game.file = folder / "game.exe";
    expect(decoded(gameIcon(game, {}), "a program's icon").width == 48, "the program's own");
    game.iconSource = folder / "other.ico";
    expect(decoded(gameIcon(game, {}), "a shortcut's icon").width == 24,
           "what the shortcut names wins");
    game.iconSource = folder / "gone.ico";
    expect(decoded(gameIcon(game, {}), "a stale shortcut").width == 48,
           "a shortcut's icon that is gone gives way to the program's");

    const fs::path bare = root / "bare-game";
    write(bare / "game.exe", peProgram({}));
    write(bare / "game.ico", icoFile({iconDib(20, 1, 2, 3)}, {20}));
    Game beside;
    beside.file = bare / "game.exe";
    expect(decoded(gameIcon(beside, {}), "an .ico beside").width == 20,
           "a program with no icon takes the .ico beside it");

    const fs::path themes = root / "share" / "icons";
    write(themes / "hicolor" / "128x128" / "apps" / "dino.png", pngOf(128));
    write(themes / "hicolor" / "48x48" / "apps" / "dino.png", pngOf(48));
    Game themed;
    themed.iconSource = "dino";
    expect(decoded(gameIcon(themed, {themes}), "a theme icon").width == 128,
           "a .desktop entry's icon name is the theme's largest");
    themed.iconSource = "not-there";
    expect(!gameIcon(themed, {themes}), "a name no theme has is no icon");
}

} // namespace

int main() try {
    const opensu::test::ScratchDir scratch{OPENSU_TEST_SCRATCH, "game_icon"};
    testProgram(scratch.path());
    testDibs();
    testIco();
    testIcns();
    testOversized();
    testHostile(scratch.path());
    testGameIcon(scratch.path());
    return 0;
} catch (...) {
    return opensu::test::escaped();
}
